#!/usr/bin/env python3
"""Owned native SFN observability capture; no provider implementation or test edits."""
import copy
from datetime import datetime, timezone, timedelta
import json
import os
from pathlib import Path
import sys
import time
import uuid

import boto3
from botocore.config import Config
from botocore.exceptions import ClientError

ROOT = Path('/home/r/dev/minor/stackd')
sys.path.insert(0, str(ROOT / 'scripts/aws'))
from aws_cli import observe

ACCOUNT = '000000000000'
REGION = 'us-west-2'
PREFIX = 'sd-sfn-obs-b2f1172ce2'
OUT = ROOT / 'testdata/aws/stepfunctions/observability.json'
ROLE = PREFIX + '-execution'
ROLE_ARN = f'arn:aws:iam::{ACCOUNT}:role/{ROLE}'
GROUP = '/aws/vendedlogs/states/' + PREFIX
GROUP_ARN = f'arn:aws:logs:{REGION}:{ACCOUNT}:log-group:{GROUP}'
MACHINES = {k: f'arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{PREFIX}-{k}' for k in ('standard', 'express')}
ENV = dict(os.environ, AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_PAGER='', AWS_MAX_ATTEMPTS='2')
CFG = Config(region_name=REGION, connect_timeout=5, read_timeout=15, retries={'max_attempts': 1})
SESSION = boto3.Session(region_name=REGION)
CLIENTS = {name: SESSION.client('stepfunctions' if name == 'sfn' else name, config=CFG) for name in ('sts', 'iam', 'logs', 'sfn', 'events', 'sqs', 'cloudwatch', 'cloudtrail')}
BEGIN = datetime.now(timezone.utc)
MONO = time.monotonic()
CAP = {
    'caller_account': ACCOUNT, 'region': REGION, 'started_at': BEGIN.isoformat(),
    'scope': 'Two machines, one role, one log group with only its own RESOURCE-scoped policy, one default-bus rule and queue, eight short Pass/Fail/Wait executions. No account-scoped policy, trail, Lake, or existing-resource mutation.',
    'serialization': 'Boto3 response dictionaries retained including ResponseMetadata; datetime objects serialized as ISO-8601 strings. SQS receipt handles and temporary STS credentials are redacted. CloudTrail LookupEvents responses retain only prefix-correlated Events, unchanged, and report excluded counts.',
    'sources': [
        {'url': 'https://docs.aws.amazon.com/step-functions/latest/dg/cw-logs.html', 'read_at': BEGIN.isoformat(), 'claims': ['Delivery is best effort.', 'ALL logs every type; ERROR includes FailStateEntered and ExecutionFailed/TimedOut/Aborted; FATAL excludes FailStateEntered; OFF logs none.', 'Express GetExecutionHistory is unavailable.']},
        {'url': 'https://docs.aws.amazon.com/step-functions/latest/dg/eventbridge-integration.html', 'read_at': BEGIN.isoformat(), 'claims': ['Only Standard workflows emit status events; best effort and potentially out of order.', 'Envelope source aws.states and detail-type Step Functions Execution Status Change.']},
        {'url': 'https://docs.aws.amazon.com/step-functions/latest/dg/procedure-cw-metrics.html', 'read_at': BEGIN.isoformat(), 'claims': ['AWS/States with StateMachineArn dimensions; delivery best effort.', 'ExecutionsStarted emits 1 then 0 on completion, hence SampleCount 2 and Sum 1 per execution.']},
        {'url': 'https://docs.aws.amazon.com/step-functions/latest/dg/procedure-cloud-trail.html', 'read_at': BEGIN.isoformat(), 'claims': ['StartExecution and control/read APIs are management events.', 'Current documentation explicitly lists StartSyncExecution and InvokeHTTPEndpoint as data events for AWS::StepFunctions::StateMachine.', 'Event history does not record data events. This supersedes older SDK language claiming StartSyncExecution is entirely unlogged.']},
        {'url': 'https://docs.aws.amazon.com/step-functions/latest/apireference/API_StartSyncExecution.html', 'read_at': BEGIN.isoformat(), 'claims': ['Read current page: no globally-unlogged note; synchronous failure returns HTTP 200 with FAILED status.']},
        {'url': 'https://docs.aws.amazon.com/AmazonCloudWatchLogs/latest/APIReference/API_PutResourcePolicy.html', 'read_at': BEGIN.isoformat(), 'claims': ['A resourceArn policy applies only to that LogGroup.']},
        {'path': 'scripts/aws/aws_cli.py', 'role': 'Shared native transport used for caller and resource-policy preflight.'},
        {'path': __file__, 'content': Path(__file__).read_text()},
    ],
    'owned_resources': {'prefix': PREFIX, 'state_machines': MACHINES, 'role': ROLE_ARN, 'log_group': GROUP_ARN, 'rule_name': PREFIX, 'executions': []},
    'observations': [], 'cleanup': {'complete': False},
}
if OUT.exists():
    CAP['setup_attempts'] = [json.loads(OUT.read_text())]
CREATED = {'role': False, 'group': False, 'policy': False, 'rule': False, 'queue': None, 'machines': []}
CONTROL = None
DEADLINE = None
LAST_COLLECT = 0
LOG_EVENTS = {}
EB_EVENTS = {}
AUDIT_EVENTS = {}


def clean(value):
    if isinstance(value, datetime):
        return value.isoformat()
    if isinstance(value, list):
        return [clean(v) for v in value]
    if isinstance(value, dict):
        return {k: ('[REDACTED]' if k in ('SecretAccessKey', 'SessionToken', 'ReceiptHandle') else clean(v)) for k, v in value.items()}
    return value


def save():
    OUT.write_text(json.dumps(clean(CAP), indent=2) + '\n')


def note(label, service, operation, params, result, began):
    CAP['observations'].append({'label': label, 'service': service, 'operation': operation, 'request': clean(params), 'elapsed_seconds': round(time.monotonic() - MONO, 3), 'observed_at': datetime.now(timezone.utc).isoformat(), 'call_duration_seconds': round(time.monotonic() - began, 3), 'response': clean(result)})
    save()


def call(label, service, operation, params=None, strict=True, client=None):
    params = params or {}
    began = time.monotonic()
    try:
        raw = getattr(client or CLIENTS[service], operation)(**params)
        result = {'code': 'Success', 'output': raw}
    except ClientError as exc:
        result = {'code': exc.response['Error']['Code'], 'error': exc.response}
    note(label, service, operation, params, result, began)
    if strict and result['code'] != 'Success':
        raise RuntimeError(label + ': ' + result['code'])
    return result


def output(*args, **kwargs):
    return call(*args, **kwargs)['output']


def logging(level='ALL', data=True):
    return {'level': level, 'includeExecutionData': data, 'destinations': [{'cloudWatchLogsLogGroup': {'logGroupArn': GROUP_ARN + ':*'}}]}


def definition(kind):
    if kind == 'pass':
        return {'StartAt': 'ShortWait', 'States': {'ShortWait': {'Type': 'Wait', 'Seconds': 1, 'Next': 'Pass'}, 'Pass': {'Type': 'Pass', 'Parameters': {'case.$': '$.case', 'result': 'native-pass', 'nested': {'n': 7}}, 'End': True}}}
    if kind == 'fail':
        return {'StartAt': 'Fail', 'States': {'Fail': {'Type': 'Fail', 'Error': 'ProbeFailure', 'Cause': 'Owned observability failure'}}}
    result = {'StartAt': 'ShortWait', 'States': {'ShortWait': {'Type': 'Wait', 'Seconds': 10, 'Next': 'Pass'}, 'Pass': {'Type': 'Pass', 'End': True}}}
    if kind == 'timeout':
        result['TimeoutSeconds'] = 2
    return result


def configure(kind, state, level, data):
    output(f'{kind}-update-{state}-{level}-{data}', 'sfn', 'update_state_machine', {'stateMachineArn': MACHINES[kind], 'definition': json.dumps(definition(state)), 'loggingConfiguration': logging(level, data)}, client=CONTROL)
    time.sleep(10)
    output(f'{kind}-describe-config-{state}-{level}-{data}', 'sfn', 'describe_state_machine', {'stateMachineArn': MACHINES[kind]})


def execute(kind, case, level, data, abort=False):
    global DEADLINE
    if DEADLINE is None:
        DEADLINE = time.monotonic() + 300
        CAP['observation_window'] = {'started_at': datetime.now(timezone.utc).isoformat(), 'maximum_seconds': 300, 'definition': 'One wall-clock window from the first execution start; no log/metric polling after its deadline.'}
    if len(CAP['owned_resources']['executions']) >= 8:
        raise RuntimeError('Execution cap exceeded')
    operation = 'start_sync_execution' if kind == 'express' else 'start_execution'
    params = {'stateMachineArn': MACHINES[kind], 'name': case, 'input': json.dumps({'case': case, 'payload': {'visible': True, 'number': 42}, 'unicode': 'native-\u03bb'}, separators=(',', ':'))}
    response = output(case + '-start', 'sfn', operation, params)
    execution = {'case': case, 'kind': kind, 'level': level, 'includeExecutionData': data, 'arn': response['executionArn'], 'started_at': datetime.now(timezone.utc).isoformat(), 'status': response.get('status')}
    CAP['owned_resources']['executions'].append(execution)
    save()
    if kind == 'standard':
        if abort:
            output(case + '-stop', 'sfn', 'stop_execution', {'executionArn': execution['arn'], 'error': 'ProbeAbort', 'cause': 'Owned observability abort'})
        terminal_deadline = time.monotonic() + 35
        while time.monotonic() < terminal_deadline:
            response = output(case + '-describe', 'sfn', 'describe_execution', {'executionArn': execution['arn']})
            if response['status'] != 'RUNNING':
                execution['status'] = response['status']
                break
            time.sleep(1)
        if execution['status'] is None:
            raise RuntimeError('Owned execution did not terminate promptly')
        output(case + '-history-data', 'sfn', 'get_execution_history', {'executionArn': execution['arn'], 'includeExecutionData': True})
        if not data:
            output(case + '-history-no-data', 'sfn', 'get_execution_history', {'executionArn': execution['arn'], 'includeExecutionData': False})
    else:
        if case == 'express-all-data-pass':
            call(case + '-history-unsupported', 'sfn', 'get_execution_history', {'executionArn': execution['arn']}, strict=False)
            call(case + '-describe-unsupported', 'sfn', 'describe_execution', {'executionArn': execution['arn']}, strict=False)
    save()
    collect(False)


def collect(audit=True):
    if DEADLINE is None or time.monotonic() >= DEADLINE:
        return
    got = output('collect-log-history', 'logs', 'filter_log_events', {'logGroupName': GROUP, 'startTime': int(BEGIN.timestamp() * 1000), 'limit': 1000})
    for event in got.get('events', []):
        LOG_EVENTS.setdefault(event['eventId'], {'first_observed_at': datetime.now(timezone.utc).isoformat(), 'raw': event})
    if time.monotonic() >= DEADLINE:
        return
    for _ in range(4):
        got = output('collect-eventbridge-queue', 'sqs', 'receive_message', {'QueueUrl': CREATED['queue'], 'MaxNumberOfMessages': 10, 'WaitTimeSeconds': 0, 'MessageSystemAttributeNames': ['All'], 'MessageAttributeNames': ['All']})
        for msg in got.get('Messages', []):
            envelope = json.loads(msg['Body'])
            EB_EVENTS.setdefault(envelope['id'], {'first_observed_at': datetime.now(timezone.utc).isoformat(), 'envelope': envelope, 'message': clean(msg)})
            output('acknowledge-owned-event', 'sqs', 'delete_message', {'QueueUrl': CREATED['queue'], 'ReceiptHandle': msg['ReceiptHandle']})
        if len(got.get('Messages', [])) < 10 or time.monotonic() >= DEADLINE:
            break
    if audit and time.monotonic() < DEADLINE:
        token = None
        audit_end = datetime.now(timezone.utc)
        for page in range(4):
            params = {'LookupAttributes': [{'AttributeKey': 'EventSource', 'AttributeValue': 'states.amazonaws.com'}], 'StartTime': BEGIN - timedelta(seconds=2), 'EndTime': audit_end, 'MaxResults': 50}
            if token:
                params['NextToken'] = token
            began = time.monotonic()
            raw = CLIENTS['cloudtrail'].lookup_events(**params)
            matching = [event for event in raw.get('Events', []) if PREFIX in event.get('CloudTrailEvent', '')]
            filtered = dict(raw, Events=matching)
            result = {'code': 'Success', 'output': filtered, 'projection': {'owned_prefix': PREFIX, 'unrelated_events_omitted': len(raw.get('Events', [])) - len(matching)}}
            note('lookup-owned-management-events', 'cloudtrail', 'lookup_events', params, result, began)
            for event in matching:
                AUDIT_EVENTS.setdefault(event['EventId'], {'first_observed_at': datetime.now(timezone.utc).isoformat(), 'raw': event, 'event': json.loads(event['CloudTrailEvent'])})
            token = raw.get('NextToken')
            if not token or time.monotonic() >= DEADLINE:
                break
            time.sleep(0.6)
    save()


def metrics(label):
    names = ['ExecutionsStarted', 'ExecutionsSucceeded', 'ExecutionsFailed', 'ExecutionsAborted', 'ExecutionsTimedOut', 'ExecutionTime']
    for kind, arn in MACHINES.items():
        for metric in names + (['ExpressExecutionBilledDuration', 'ExpressExecutionBilledMemory', 'ExpressExecutionMemory'] if kind == 'express' else []):
            if time.monotonic() >= DEADLINE:
                return
            output(label + '-' + kind + '-' + metric, 'cloudwatch', 'get_metric_statistics', {'Namespace': 'AWS/States', 'MetricName': metric, 'Dimensions': [{'Name': 'StateMachineArn', 'Value': arn}], 'StartTime': BEGIN - timedelta(minutes=1), 'EndTime': datetime.now(timezone.utc) + timedelta(seconds=1), 'Period': 60, 'Statistics': ['Sum', 'SampleCount', 'Minimum', 'Maximum', 'Average']})


def cleanup():
    errors = []
    for execution in CAP['owned_resources']['executions']:
        if execution['kind'] == 'standard':
            result = call('cleanup-terminal-execution', 'sfn', 'describe_execution', {'executionArn': execution['arn']}, strict=False)
            if result['code'] == 'Success' and result['output']['status'] == 'RUNNING':
                call('cleanup-stop-execution', 'sfn', 'stop_execution', {'executionArn': execution['arn'], 'error': 'ProbeCleanup'}, strict=False)
                result = call('cleanup-terminal-after-stop', 'sfn', 'describe_execution', {'executionArn': execution['arn']}, strict=False)
            if result['code'] == 'Success':
                execution['cleanup_status'] = result['output']['status']
    for arn in CREATED['machines']:
        call('cleanup-delete-machine', 'sfn', 'delete_state_machine', {'stateMachineArn': arn}, strict=False)
    if CREATED['rule']:
        call('cleanup-remove-target', 'events', 'remove_targets', {'Rule': PREFIX, 'Ids': ['queue']}, strict=False)
        call('cleanup-delete-rule', 'events', 'delete_rule', {'Name': PREFIX}, strict=False)
    if CREATED['queue']:
        call('cleanup-delete-queue', 'sqs', 'delete_queue', {'QueueUrl': CREATED['queue']}, strict=False)
    if CREATED['policy']:
        call('cleanup-delete-owned-log-policy', 'logs', 'delete_resource_policy', {'resourceArn': GROUP_ARN}, strict=False)
    if CREATED['group']:
        call('cleanup-delete-log-group', 'logs', 'delete_log_group', {'logGroupName': GROUP}, strict=False)
    if CREATED['role']:
        call('cleanup-delete-role-policy', 'iam', 'delete_role_policy', {'RoleName': ROLE, 'PolicyName': PREFIX}, strict=False)
        call('cleanup-delete-role', 'iam', 'delete_role', {'RoleName': ROLE}, strict=False)
    deadline = time.monotonic() + 180
    pending = set(CREATED['machines'])
    while pending and time.monotonic() < deadline:
        for arn in list(pending):
            result = call('cleanup-machine-absence', 'sfn', 'describe_state_machine', {'stateMachineArn': arn}, strict=False)
            if result['code'] == 'StateMachineDoesNotExist':
                pending.remove(arn)
        if pending:
            time.sleep(5)
    checks = {'machines_absent': not pending}
    if CREATED['role']:
        checks['role_absent'] = call('cleanup-role-absence', 'iam', 'get_role', {'RoleName': ROLE}, strict=False)['code'] == 'NoSuchEntity'
    if CREATED['queue']:
        checks['queue_absent'] = call('cleanup-queue-absence', 'sqs', 'get_queue_attributes', {'QueueUrl': CREATED['queue'], 'AttributeNames': ['QueueArn']}, strict=False)['code'] in ('AWS.SimpleQueueService.NonExistentQueue', 'QueueDoesNotExist')
    if CREATED['rule']:
        checks['rule_absent'] = call('cleanup-rule-absence', 'events', 'describe_rule', {'Name': PREFIX}, strict=False)['code'] == 'ResourceNotFoundException'
    groups = output('cleanup-log-group-absence', 'logs', 'describe_log_groups', {'logGroupNamePrefix': GROUP})
    checks['log_group_absent'] = not any(group['logGroupName'] == GROUP for group in groups.get('logGroups', []))
    policies = output('cleanup-resource-policies', 'logs', 'describe_resource_policies', {})
    scoped = output('cleanup-owned-resource-policy-absence', 'logs', 'describe_resource_policies', {'policyScope': 'RESOURCE', 'resourceArn': GROUP_ARN})
    checks['owned_log_policy_absent'] = not any(policy.get('policyName') == PREFIX or policy.get('resourceArn') == GROUP_ARN for policy in scoped.get('resourcePolicies', []))
    checks['account_scoped_policies_unchanged'] = policies.get('resourcePolicies', []) == CAP.get('baseline_account_resource_policies', [])
    checks['all_executions_terminal'] = all(e.get('cleanup_status', e.get('status')) in ('SUCCEEDED', 'FAILED', 'TIMED_OUT', 'ABORTED') for e in CAP['owned_resources']['executions'])
    CAP['cleanup'] = {'complete': all(checks.values()), 'checks': checks, 'completed_at': datetime.now(timezone.utc).isoformat()}
    save()


try:
    actor = observe('sts', 'get-caller-identity', {}, ENV)
    CAP['caller'] = actor
    if actor.get('output', {}).get('Account') != ACCOUNT or not actor['output']['Arn'].endswith(':user/Delegated'):
        raise RuntimeError('Not the designated Delegated caller')
    baseline = observe('logs', 'describe-resource-policies', {}, ENV)
    CAP['baseline_resource_policy_response'] = baseline
    CAP['baseline_account_resource_policies'] = baseline['output'].get('resourcePolicies', [])
    output('create-owned-log-group', 'logs', 'create_log_group', {'logGroupName': GROUP, 'tags': {'stackd-probe': PREFIX}})
    CREATED['group'] = True
    policy = {'Version': '2012-10-17', 'Statement': [{'Sid': 'OwnedDelivery', 'Effect': 'Allow', 'Principal': {'Service': 'delivery.logs.amazonaws.com'}, 'Action': ['logs:CreateLogStream', 'logs:PutLogEvents'], 'Resource': GROUP_ARN + ':*', 'Condition': {'StringEquals': {'aws:SourceAccount': ACCOUNT}, 'ArnLike': {'aws:SourceArn': f'arn:aws:logs:{REGION}:{ACCOUNT}:*'}}}]}
    output('create-owned-resource-scoped-log-policy', 'logs', 'put_resource_policy', {'resourceArn': GROUP_ARN, 'policyDocument': json.dumps(policy)})
    CREATED['policy'] = True
    trust = {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Principal': {'Service': 'states.amazonaws.com'}, 'Action': 'sts:AssumeRole', 'Condition': {'StringEquals': {'aws:SourceAccount': ACCOUNT}, 'ArnLike': {'aws:SourceArn': f'arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{PREFIX}-*'}}}, {'Effect': 'Allow', 'Principal': {'AWS': actor['output']['Arn']}, 'Action': 'sts:AssumeRole'}]}
    output('create-owned-role', 'iam', 'create_role', {'RoleName': ROLE, 'AssumeRolePolicyDocument': json.dumps(trust), 'Tags': [{'Key': 'stackd-probe', 'Value': PREFIX}]})
    CREATED['role'] = True
    permissions = {'Version': '2012-10-17', 'Statement': [
        {'Effect': 'Allow', 'Action': ['logs:CreateLogDelivery', 'logs:GetLogDelivery', 'logs:UpdateLogDelivery', 'logs:DeleteLogDelivery', 'logs:ListLogDeliveries', 'logs:DescribeResourcePolicies', 'logs:DescribeLogGroups'], 'Resource': '*'},
        {'Effect': 'Allow', 'Action': ['logs:CreateLogStream', 'logs:PutLogEvents'], 'Resource': GROUP_ARN + ':*'},
        {'Effect': 'Allow', 'Action': 'logs:PutResourcePolicy', 'Resource': GROUP_ARN},
        {'Effect': 'Deny', 'Action': 'logs:PutResourcePolicy', 'NotResource': GROUP_ARN},
        {'Effect': 'Allow', 'Action': ['states:CreateStateMachine', 'states:UpdateStateMachine', 'states:DescribeStateMachine'], 'Resource': list(MACHINES.values())},
        {'Effect': 'Allow', 'Action': 'iam:PassRole', 'Resource': ROLE_ARN, 'Condition': {'StringEquals': {'iam:PassedToService': 'states.amazonaws.com'}}},
    ]}
    output('put-owned-role-permissions', 'iam', 'put_role_policy', {'RoleName': ROLE, 'PolicyName': PREFIX, 'PolicyDocument': json.dumps(permissions)})
    time.sleep(15)
    assumed = output('assume-owned-guarded-control-role', 'sts', 'assume_role', {'RoleArn': ROLE_ARN, 'RoleSessionName': PREFIX})
    creds = assumed['Credentials']
    CONTROL = boto3.client('stepfunctions', region_name=REGION, config=CFG, aws_access_key_id=creds['AccessKeyId'], aws_secret_access_key=creds['SecretAccessKey'], aws_session_token=creds['SessionToken'])
    for kind, arn in MACHINES.items():
        response = output('create-' + kind + '-machine', 'sfn', 'create_state_machine', {'name': PREFIX + '-' + kind, 'roleArn': ROLE_ARN, 'type': kind.upper(), 'definition': json.dumps(definition('pass')), 'loggingConfiguration': logging()}, client=CONTROL)
        CREATED['machines'].append(response['stateMachineArn'])
    CAP['created_account_resource_policies'] = output('verify-no-account-log-policy-mutation', 'logs', 'describe_resource_policies', {}).get('resourcePolicies', [])
    if CAP['created_account_resource_policies'] != CAP['baseline_account_resource_policies']:
        raise RuntimeError('Unexpected account-level log policy mutation')
    queue = output('create-owned-event-queue', 'sqs', 'create_queue', {'QueueName': PREFIX, 'Attributes': {'MessageRetentionPeriod': '600'}, 'tags': {'stackd-probe': PREFIX}})
    CREATED['queue'] = queue['QueueUrl']
    queue_arn = output('read-owned-queue-arn', 'sqs', 'get_queue_attributes', {'QueueUrl': CREATED['queue'], 'AttributeNames': ['QueueArn']})['Attributes']['QueueArn']
    CAP['owned_resources']['queue'] = {'arn': queue_arn, 'url': CREATED['queue']}
    rule = output('create-owned-status-rule', 'events', 'put_rule', {'Name': PREFIX, 'EventPattern': json.dumps({'source': ['aws.states'], 'detail-type': ['Step Functions Execution Status Change'], 'detail': {'stateMachineArn': list(MACHINES.values())}}), 'State': 'ENABLED', 'Tags': [{'Key': 'stackd-probe', 'Value': PREFIX}]})
    CREATED['rule'] = True
    CAP['owned_resources']['rule_arn'] = rule['RuleArn']
    queue_policy = {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Principal': {'Service': 'events.amazonaws.com'}, 'Action': 'sqs:SendMessage', 'Resource': queue_arn, 'Condition': {'ArnEquals': {'aws:SourceArn': rule['RuleArn']}}}]}
    output('allow-only-owned-rule', 'sqs', 'set_queue_attributes', {'QueueUrl': CREATED['queue'], 'Attributes': {'Policy': json.dumps(queue_policy)}})
    target = output('attach-owned-event-target', 'events', 'put_targets', {'Rule': PREFIX, 'Targets': [{'Id': 'queue', 'Arn': queue_arn, 'RetryPolicy': {'MaximumEventAgeInSeconds': 60, 'MaximumRetryAttempts': 0}}]})
    if target['FailedEntryCount']:
        raise RuntimeError('Target registration failed')
    time.sleep(8)
    execute('standard', 'standard-all-data-pass', 'ALL', True)
    execute('express', 'express-all-data-pass', 'ALL', True)
    configure('standard', 'wait', 'ALL', True)
    execute('standard', 'standard-all-data-abort', 'ALL', True, abort=True)
    configure('express', 'pass', 'ALL', False)
    execute('express', 'express-all-no-data-pass', 'ALL', False)
    configure('standard', 'fail', 'ERROR', False)
    execute('standard', 'standard-error-no-data-fail', 'ERROR', False)
    configure('express', 'fail', 'ERROR', True)
    execute('express', 'express-error-data-fail', 'ERROR', True)
    configure('standard', 'timeout', 'FATAL', False)
    execute('standard', 'standard-fatal-no-data-timeout', 'FATAL', False)
    configure('express', 'fail', 'OFF', True)
    execute('express', 'express-off-data-fail', 'OFF', True)
    metrics('metrics-initial')
    while time.monotonic() < DEADLINE - 25:
        collect(True)
        time.sleep(min(25, max(0, DEADLINE - 25 - time.monotonic())))
    collect(True)
    metrics('metrics-final')
    CAP['observation_window']['finished_at'] = datetime.now(timezone.utc).isoformat()
    CAP['observation_window']['actual_seconds'] = round(300 - max(0, DEADLINE - time.monotonic()), 3)
    CAP['collected'] = {'eventbridge': list(EB_EVENTS.values()), 'logs': list(LOG_EVENTS.values()), 'cloudtrail': list(AUDIT_EVENTS.values())}
    CAP['capture_complete'] = True
except BaseException as exc:
    CAP['failure'] = {'type': type(exc).__name__, 'message': str(exc)}
    CAP['collected'] = {'eventbridge': list(EB_EVENTS.values()), 'logs': list(LOG_EVENTS.values()), 'cloudtrail': list(AUDIT_EVENTS.values())}
    save()
    raise
finally:
    cleanup()
    print(json.dumps({'fixture': str(OUT), 'prefix': PREFIX, 'executions': len(CAP['owned_resources']['executions']), 'capture_complete': CAP.get('capture_complete', False), 'cleanup': CAP['cleanup']}, indent=2), flush=True)

#!/usr/bin/env python3
"""Owned native SFN observability capture; no provider implementation or test edits."""
import copy
from datetime import datetime, timezone, timedelta
import json
import os
from pathlib import Path
import sys
import time
import uuid

import boto3
from botocore.config import Config
from botocore.exceptions import ClientError

ROOT = Path('/home/r/dev/minor/stackd')
sys.path.insert(0, str(ROOT / 'scripts/aws'))
from aws_cli import observe

ACCOUNT = '000000000000'
REGION = 'us-west-2'
PREFIX = 'sd-sfn-obs-' + uuid.uuid4().hex[:10]
OUT = ROOT / 'testdata/aws/stepfunctions/observability.json'
ROLE = PREFIX + '-execution'
ROLE_ARN = f'arn:aws:iam::{ACCOUNT}:role/{ROLE}'
GROUP = '/aws/vendedlogs/states/' + PREFIX
GROUP_ARN = f'arn:aws:logs:{REGION}:{ACCOUNT}:log-group:{GROUP}'
MACHINES = {k: f'arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{PREFIX}-{k}' for k in ('standard', 'express')}
ENV = dict(os.environ, AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_PAGER='', AWS_MAX_ATTEMPTS='2')
CFG = Config(region_name=REGION, connect_timeout=5, read_timeout=15, retries={'max_attempts': 1})
SESSION = boto3.Session(region_name=REGION)
