    output('create-owned-role', 'iam', 'create_role', {'RoleName': ROLE, 'AssumeRolePolicyDocument': json.dumps(trust), 'Tags': [{'Key': 'stackd-probe', 'Value': PREFIX}]})
    CREATED['role'] = True
    permissions = {'Version': '2012-10-17', 'Statement': [
        {'Effect': 'Allow', 'Action': ['logs:CreateLogDelivery', 'logs:GetLogDelivery', 'logs:UpdateLogDelivery', 'logs:DeleteLogDelivery', 'logs:ListLogDeliveries', 'logs:DescribeResourcePolicies', 'logs:DescribeLogGroups'], 'Resource': '*'},
        {'Effect': 'Allow', 'Action': ['logs:CreateLogStream', 'logs:PutLogEvents'], 'Resource': GROUP_ARN + ':*'},
        {'Effect': 'Allow', 'Action': 'logs:PutResourcePolicy', 'Resource': GROUP_ARN},
        {'Effect': 'Deny', 'Action': 'logs:PutResourcePolicy', 'NotResource': GROUP_ARN},
        {'Effect': 'Allow', 'Action': ['states:CreateStateMachine', 'states:UpdateStateMachine', 'states:DescribeStateMachine'], 'Resource': list(MACHINES.values())},
        {'Effect': 'Allow', 'Action': 'iam:PassRole', 'Resource': ROLE_ARN, 'Condition': {'StringEquals': {'iam:PassedToService': 'states.amazonaws.com'}}},
    ]}
    output('put-owned-role-permissions', 'iam', 'put_role_policy', {'RoleName': ROLE, 'PolicyName': PREFIX, 'PolicyDocument': json.dumps(permissions)})
    time.sleep(15)
    assumed = output('assume-owned-guarded-control-role', 'sts', 'assume_role', {'RoleArn': ROLE_ARN, 'RoleSessionName': PREFIX})
    creds = assumed['Credentials']
    CONTROL = boto3.client('stepfunctions', region_name=REGION, config=CFG, aws_access_key_id=creds['AccessKeyId'], aws_secret_access_key=creds['SecretAccessKey'], aws_session_token=creds['SessionToken'])
    for kind, arn in MACHINES.items():
        response = output('create-' + kind + '-machine', 'sfn', 'create_state_machine', {'name': PREFIX + '-' + kind, 'roleArn': ROLE_ARN, 'type': kind.upper(), 'definition': json.dumps(definition('pass')), 'loggingConfiguration': logging()}, client=CONTROL)
        CREATED['machines'].append(response['stateMachineArn'])
    CAP['created_account_resource_policies'] = output('verify-no-account-log-policy-mutation', 'logs', 'describe_resource_policies', {}).get('resourcePolicies', [])
    if CAP['created_account_resource_policies'] != CAP['baseline_account_resource_policies']:
        raise RuntimeError('Unexpected account-level log policy mutation')
    queue = output('create-owned-event-queue', 'sqs', 'create_queue', {'QueueName': PREFIX, 'Attributes': {'MessageRetentionPeriod': '600'}, 'tags': {'stackd-probe': PREFIX}})
    CREATED['queue'] = queue['QueueUrl']
    queue_arn = output('read-owned-queue-arn', 'sqs', 'get_queue_attributes', {'QueueUrl': CREATED['queue'], 'AttributeNames': ['QueueArn']})['Attributes']['QueueArn']
    CAP['owned_resources']['queue'] = {'arn': queue_arn, 'url': CREATED['queue']}
    rule = output('create-owned-status-rule', 'events', 'put_rule', {'Name': PREFIX, 'EventPattern': json.dumps({'source': ['aws.states'], 'detail-type': ['Step Functions Execution Status Change'], 'detail': {'stateMachineArn': list(MACHINES.values())}}), 'State': 'ENABLED', 'Tags': [{'Key': 'stackd-probe', 'Value': PREFIX}]})
    CREATED['rule'] = True
    CAP['owned_resources']['rule_arn'] = rule['RuleArn']
    queue_policy = {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Principal': {'Service': 'events.amazonaws.com'}, 'Action': 'sqs:SendMessage', 'Resource': queue_arn, 'Condition': {'ArnEquals': {'aws:SourceArn': rule['RuleArn']}}}]}
    output('allow-only-owned-rule', 'sqs', 'set_queue_attributes', {'QueueUrl': CREATED['queue'], 'Attributes': {'Policy': json.dumps(queue_policy)}})
    target = output('attach-owned-event-target', 'events', 'put_targets', {'Rule': PREFIX, 'Targets': [{'Id': 'queue', 'Arn': queue_arn, 'RetryPolicy': {'MaximumEventAgeInSeconds': 60, 'MaximumRetryAttempts': 0}}]})
    if target['FailedEntryCount']:
        raise RuntimeError('Target registration failed')
    time.sleep(8)
    execute('standard', 'standard-all-data-pass', 'ALL', True)
    execute('express', 'express-all-data-pass', 'ALL', True)
    configure('standard', 'wait', 'ALL', True)
    execute('standard', 'standard-all-data-abort', 'ALL', True, abort=True)
    configure('express', 'pass', 'ALL', False)
    execute('express', 'express-all-no-data-pass', 'ALL', False)
    configure('standard', 'fail', 'ERROR', False)
    execute('standard', 'standard-error-no-data-fail', 'ERROR', False)
    configure('express', 'fail', 'ERROR', True)
    execute('express', 'express-error-data-fail', 'ERROR', True)
    configure('standard', 'timeout', 'FATAL', False)
    execute('standard', 'standard-fatal-no-data-timeout', 'FATAL', False)
    configure('express', 'fail', 'OFF', True)
    execute('express', 'express-off-data-fail', 'OFF', True)
    metrics('metrics-initial')
    while time.monotonic() < DEADLINE - 25:
        collect(True)
        time.sleep(min(25, max(0, DEADLINE - 25 - time.monotonic())))
    collect(True)
    metrics('metrics-final')
    CAP['observation_window']['finished_at'] = datetime.now(timezone.utc).isoformat()
    CAP['observation_window']['actual_seconds'] = round(300 - max(0, DEADLINE - time.monotonic()), 3)
    CAP['collected'] = {'eventbridge': list(EB_EVENTS.values()), 'logs': list(LOG_EVENTS.values()), 'cloudtrail': list(AUDIT_EVENTS.values())}
    CAP['capture_complete'] = True
except BaseException as exc:
    CAP['failure'] = {'type': type(exc).__name__, 'message': str(exc)}
    CAP['collected'] = {'eventbridge': list(EB_EVENTS.values()), 'logs': list(LOG_EVENTS.values()), 'cloudtrail': list(AUDIT_EVENTS.values())}
    save()
    raise
finally:
    cleanup()
    print(json.dumps({'fixture': str(OUT), 'prefix': PREFIX, 'executions': len(CAP['owned_resources']['executions']), 'capture_complete': CAP.get('capture_complete', False), 'cleanup': CAP['cleanup']}, indent=2), flush=True)
